package cn.iocoder.yudao.module.hrm.service.payroll;
import cn.iocoder.yudao.framework.test.core.ut.BaseDbUnitTest;
import cn.iocoder.yudao.framework.common.util.json.JsonUtils;
import cn.iocoder.yudao.framework.mybatis.core.query.LambdaQueryWrapperX;
import cn.iocoder.yudao.module.hrm.controller.admin.payroll.vo.*;
import cn.iocoder.yudao.module.hrm.controller.admin.payroll.vo.HrmPayrollReviewVO.*;
import cn.iocoder.yudao.module.hrm.dal.dataobject.payroll.*;
import cn.iocoder.yudao.module.hrm.dal.mysql.payroll.*;
import org.junit.jupiter.api.*;
import org.springframework.context.annotation.Import;
import org.springframework.boot.test.mock.mockito.MockBean;
import javax.annotation.Resource;
import java.time.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
@Import({HrmPayrollReviewService.class,HrmPayrollWorkbenchService.class,HrmPayrollRequirementAccessService.class,HrmPayrollRequirementProjectService.class,HrmPayrollRequirementServiceImpl.class})
class HrmPayrollReviewServiceTest extends BaseDbUnitTest {
 // These tests isolate the pre-S5 contract. The real governance gate is covered by HrmPayrollGovernanceServiceTest and runtime regression.
 @org.springframework.boot.test.mock.mockito.MockBean private cn.iocoder.yudao.module.hrm.service.payroll.HrmPayrollGovernanceStore stage5Store;
 @org.springframework.boot.test.mock.mockito.MockBean private cn.iocoder.yudao.module.hrm.service.payroll.HrmPayrollGovernanceRootService stage5Roots;
 @org.springframework.boot.test.mock.mockito.MockBean private cn.iocoder.yudao.module.hrm.service.payroll.HrmPayrollGovernanceDecisionService stage5Decisions;
 @org.junit.jupiter.api.BeforeEach void stage5ContractIsolation(){
  org.mockito.Mockito.when(stage5Decisions.currentSemantic(org.mockito.ArgumentMatchers.any())).thenReturn(true);
  org.mockito.Mockito.when(stage5Roots.validRoot(org.mockito.ArgumentMatchers.anyLong(),org.mockito.ArgumentMatchers.any())).thenReturn(true);
 }

 @Resource HrmPayrollReviewService service;
 @Resource HrmPayrollRequirementService reqs;
 @Resource HrmPayrollRequirementProjectService projectService;
 @Resource HrmPayrollRequirementMapper rows;
 @Resource HrmPayrollRequirementProjectMapper projects;
 @Resource HrmPayrollRequirementProjectGrantMapper grants;
 @Resource HrmPayrollRequirementHistoryMapper histories;
 @MockBean cn.iocoder.yudao.module.system.api.user.AdminUserApi users;
 @MockBean cn.iocoder.yudao.module.system.api.permission.PermissionApi permissions;
 long p;
 String scope="{\"entities\":[101],\"organizations\":[201],\"workerTypes\":[\"TEST\"],\"scenarios\":[\"TEST\"],\"from\":\"2026-10-01\",\"to\":\"2026-10-31\",\"explanation\":\"TEST\"}";
 static String business(){return "{\"page\":\"/hrm-payroll/review\",\"contextModule\":\"OT\",\"anchor\":\"field-hours\",\"targetType\":\"FIELD\",\"role\":\"TEST HR\",\"scenario\":\"TEST overtime\",\"goal\":\"TEST collection\",\"expected\":\"TEST result\",\"normalCase\":\"TEST normal\",\"exceptionCase\":\"TEST missing\",\"calculation\":\"TEST unapproved rule\",\"unit\":\"hour\",\"precision\":\"2 decimal HALF_UP\",\"validity\":\"2026-10\",\"ruleException\":\"TEST review\",\"disputeOwnerId\":1,\"nextStep\":\"TEST review\"}";}
 @BeforeEach void setup(){cn.iocoder.yudao.framework.tenant.core.context.TenantContextHolder.setTenantId(1L);when(permissions.hasAnyPermissions(anyLong(),anyString())).thenReturn(true);for(long id=1;id<=4;id++)when(users.getUser(id)).thenReturn(new cn.iocoder.yudao.module.system.api.user.dto.AdminUserRespDTO().setId(id).setStatus(0));HrmPayrollRequirementProjectDO x=new HrmPayrollRequirementProjectDO().setProjectKey("TEST_S4").setName("TEST S4").setOwnerId(1L).setScopeJson(scope).setProjectScopeVersion(1).setMetadataVersion(1).setCustomSequence(0L);projects.insert(x);p=x.getId();for(long user=1;user<=4;user++)grant(user,String.join(",",HrmPayrollRequirementAccessService.ACTIONS),null);}
 @AfterEach void clear(){cn.iocoder.yudao.framework.tenant.core.context.TenantContextHolder.clear();}
 void grant(long user,String actions,String ids){HrmPayrollRequirementProjectGrantDO g=new HrmPayrollRequirementProjectGrantDO();g.setProjectId(p);g.setUserId(user);g.setActions(actions);g.setFullProject(ids==null);g.setRequirementIdsJson(ids);g.setCeilingJson(scope);g.setEvidence("TEST independent synthetic root");g.setValidFrom(LocalDate.of(2026,1,1));g.setValidTo(LocalDate.of(2027,1,1));grants.insert(g);}
 long create(String title){HrmPayrollRequirementSaveReqVO q=new HrmPayrollRequirementSaveReqVO();q.setProjectId(p);q.setProjectScopeVersion(1);q.setScopeMode("INHERIT");q.setCode("CUSTOM-0000");q.setModule("OT");q.setDescription(title);q.setPriority(2);q.setStatus("PENDING");q.setReadiness("MISSING");q.setBusinessContextJson(business());q.setRuleVersion("TEST V1");q.setSourceApplicability("NOT_APPLICABLE");q.setApplicabilityReason("TEST 仅讨论页面规则，不消费业务数据");q.setAcceptance("TEST expected result");q.setEvidence("TEST authorized scenario");long id=reqs.save(q,1L);reqs.assign(id,rows.selectById(id).getVersion(),2L,1L);return id;}
 <T extends Context>T ctx(T c,long id){c.setProjectId(p);c.setProjectScopeVersion(1);c.setId(id);c.setVersion(rows.selectById(id).getVersion());c.setReason("TEST independent basis");return c;}
 void decision(long id,String value){Decision c=ctx(new Decision(),id);c.setDecision(value);c.setResponsibleId(1L);c.setReevaluate("TEST review after supply");service.decide(c,1L);}
 void confirm(long id){reqs.confirm(id,rows.selectById(id).getVersion(),2L);}
 List<Long> s0(){List<Long> ids=new ArrayList<>();for(int i=0;i<46;i++){long id=create("TEST fixed S0 "+i);ids.add(id);if(i<40){decision(id,"INCLUDED");confirm(id);}else decision(id,"DEFERRED");}return ids;}
 Map<String,Object> stats(){return service.statistics(p,1L,"READ",null);}
 @SuppressWarnings("unchecked") void expected(Map<String,Object> s,int u,int e,int i,int c,int t,int d){Map<String,Object> n=(Map<String,Object>)s.get("counts");assertEquals(u,n.get("U"));assertEquals(e,n.get("E"));assertEquals(i,n.get("I"));assertEquals(c,n.get("C"));assertEquals(t,n.get("T"));assertEquals(d,n.get("D"));assertEquals(c+"/"+e,((Map<?,?>)s.get("confirmation")).get("label"));}
 @Test void fixedS0S1S2UseIndependentExpectedSetsAndRetainRemovedHistory(){List<Long> ids=s0();expected(stats(),46,46,40,40,6,0);long extra=create("TEST disputed candidate");HrmPayrollRequirementSaveReqVO q=JsonUtils.parseObject(JsonUtils.toJsonString(rows.selectById(extra)),HrmPayrollRequirementSaveReqVO.class);q.setStatus("DISPUTED");reqs.save(q,1L);expected(stats(),47,47,40,40,6,1);int before=histories.selectList().size();Decision remove=ctx(new Decision(),extra);remove.setDecision("REMOVED");remove.setRemovalKind("DUPLICATE");remove.setReplacementId(ids.get(0));service.decide(remove,1L);expected(stats(),47,46,40,40,6,0);assertEquals(before+1,histories.selectList().size());assertEquals("DISPUTED",rows.selectById(extra).getStatus());assertNotNull(rows.selectById(extra));}
 @Test void fixedS3RevisionsNeverCountHistoricalConfirmedLabels(){List<Long> ids=s0();long id=ids.get(0);HrmPayrollRequirementSaveReqVO q=JsonUtils.parseObject(JsonUtils.toJsonString(rows.selectById(id)),HrmPayrollRequirementSaveReqVO.class);q.setBusinessContextJson(business().replace("TEST overtime","TEST changed scenario"));reqs.save(q,1L);expected(stats(),46,46,40,39,6,0);assertEquals("39/40",((Map<?,?>)stats().get("includedConfirmation")).get("label"));assertFalse(((Collection<?>)stats().get("missingIncludedConfirmationIds")).isEmpty());}
 @Test void fixedS4EmptyProjectDoesNotReportHundredPercent(){Map<String,Object>s=stats();for(String key:Arrays.asList("confirmation","scopeDisposition","includedConfirmation","readiness","includedReadiness")){Map<?,?>rate=(Map<?,?>)s.get(key);assertEquals("暂无适用项（0/0）",rate.get("label"));assertNull(rate.get("percent"));}assertEquals("INDEPENDENT_PUBLISH_CHECK_REQUIRED",s.get("formalReleaseGate"));}
 @Test void scopeDecisionIsNotScopeOrMemberAlias(){long id=create("TEST scope denied");grants.delete(new LambdaQueryWrapperX<HrmPayrollRequirementProjectGrantDO>().eq(HrmPayrollRequirementProjectGrantDO::getUserId,3L));grant(3,"READ,SCOPE,MEMBER",null);Decision c=ctx(new Decision(),id);c.setDecision("INCLUDED");assertThrows(cn.iocoder.yudao.framework.common.exception.ServiceException.class,()->service.decide(c,3L));assertEquals("CANDIDATE",rows.selectById(id).getScopeDecision());}
 @Test void platformScopeDecisionRequiredSeparately(){long id=create("TEST platform");when(permissions.hasAnyPermissions(1L,"hrm:payroll:requirement:scope-decide")).thenReturn(false);Decision c=ctx(new Decision(),id);c.setDecision("INCLUDED");assertThrows(cn.iocoder.yudao.framework.common.exception.ServiceException.class,()->service.decide(c,1L));}
 @Test void deferNeedsReasonResponsibleAndReevaluationWithoutChangingReview(){long id=create("TEST deferred");confirm(id);Decision c=ctx(new Decision(),id);c.setDecision("DEFERRED");assertThrows(cn.iocoder.yudao.framework.common.exception.ServiceException.class,()->service.decide(c,1L));c.setResponsibleId(1L);c.setReevaluate("TEST supply next month");service.decide(c,1L);assertEquals("CONFIRMED",rows.selectById(id).getStatus());assertTrue((Boolean)projectService.rows(p,null,1L,"READ").get(0).getCurrentConfirmationValid());expected(stats(),1,1,0,1,1,0);}
 @Test void duplicateMustRetainSameProjectTargetAndCannotFormCycles(){long a=create("A"),b=create("B");Decision c=ctx(new Decision(),a);c.setDecision("REMOVED");c.setRemovalKind("DUPLICATE");c.setReplacementId(a);assertThrows(cn.iocoder.yudao.framework.common.exception.ServiceException.class,()->service.decide(c,1L));c.setReplacementId(b);service.decide(c,1L);Decision other=ctx(new Decision(),b);other.setDecision("REMOVED");other.setRemovalKind("DUPLICATE");other.setReplacementId(a);assertThrows(cn.iocoder.yudao.framework.common.exception.ServiceException.class,()->service.decide(other,1L));decision(a,"CANDIDATE");assertEquals("REVIEWING",rows.selectById(a).getStatus());assertNull(rows.selectById(a).getConfirmedBy());}
 @Test void implementationChangesDoNotConfirmOrInvalidateFunctionalConfirmation(){long id=create("TEST implementation");confirm(id);String tuple=rows.selectById(id).getConfirmedTupleJson();Implementation c=ctx(new Implementation(),id);c.setState("ACCEPTED");assertThrows(cn.iocoder.yudao.framework.common.exception.ServiceException.class,()->service.implementation(c,1L));c.setPage("TEST page");c.setApi("TEST API");c.setTask("TEST task");c.setEvidence("TEST unverified acceptance reference");service.implementation(c,1L);assertEquals(tuple,rows.selectById(id).getConfirmedTupleJson());assertEquals("CONFIRMED",rows.selectById(id).getStatus());assertTrue(rows.selectById(id).getImplementationJson().contains("\"conclusionVerified\":false"));}
 @Test void meetingAndReminderAreAppendOnlyReviewNotesWithActiveScopedRecipient(){long id=create("TEST notes");Collaboration c=ctx(new Collaboration(),id);c.setKind("MEETING");c.setReference("TEST meeting V1");service.collaborate(c,1L);c=ctx(new Collaboration(),id);c.setKind("REMINDER");c.setReference("TEST reminder");c.setRecipientId(3L);service.collaborate(c,1L);assertEquals(2,JsonUtils.parseArray(rows.selectById(id).getCollaborationJson(),Object.class).size());assertTrue(rows.selectById(id).getCollaborationJson().contains("IN_APP_ONLY"));}
 @Test void batchAssignmentReportsRealPartialFailureWithoutGlobalRollback(){long a=create("A"),b=create("B");Context old=ctx(new Context(),b);decision(b,"INCLUDED");BatchAssignment q=new BatchAssignment();q.setProjectId(p);q.setProjectScopeVersion(1);q.setReviewerId(4L);q.setItems(Arrays.asList(ctx(new Context(),a),old));List<Object> result=service.batch(q,1L);assertEquals(true,((Map<?,?>)result.get(0)).get("success"));assertEquals(false,((Map<?,?>)result.get(1)).get("success"));assertEquals(4L,rows.selectById(a).getReviewerId());assertEquals(2L,rows.selectById(b).getReviewerId());}
 @Test void restrictedSetsPagesAndExportsNeverExposeHiddenIdsOrWholeProjectTotals(){long a=create("Visible"),b=create("Hidden");grants.delete(new LambdaQueryWrapperX<HrmPayrollRequirementProjectGrantDO>().eq(HrmPayrollRequirementProjectGrantDO::getUserId,3L));grant(3,"READ,EXPORT","["+a+"]");Map<String,Object>s=service.statistics(p,3L,"READ",null);assertEquals(true,s.get("permissionRestricted"));assertFalse(s.containsKey("projectTotals"));assertEquals(Collections.singletonList(a),new ArrayList<>((Collection<?>)((Map<?,?>)s.get("sets")).get("U")));Map<String,Object>x=service.export(p,3L,null,null,null,null);assertEquals(1,((List<?>)x.get("requirements")).size());assertEquals(1,service.page(p,3L,null,null,null,null,1,10,"code").get("total"));}
 @Test void filterDoesNotAlterProjectCountersOrFormalGate(){long a=create("A"),b=create("B");decision(a,"INCLUDED");confirm(a);Map<String,Object>s=service.statistics(p,1L,"READ",null,null,"INCLUDED",null);assertEquals(1,((Map<?,?>)s.get("counts")).get("E"));assertEquals(2,((Map<?,?>)((Map<?,?>)s.get("projectTotals")).get("counts")).get("E"));assertEquals("INDEPENDENT_PUBLISH_CHECK_REQUIRED",s.get("formalReleaseGate"));}
 @Test void oldVersionAndCrossProjectDecisionsDoNotAddHistory(){long id=create("TEST conflict");Decision old=ctx(new Decision(),id);old.setDecision("INCLUDED");decision(id,"DEFERRED");int before=histories.selectList().size();assertThrows(cn.iocoder.yudao.framework.common.exception.ServiceException.class,()->service.decide(old,1L));assertEquals(before,histories.selectList().size());old.setVersion(rows.selectById(id).getVersion());old.setProjectId(p+100);assertThrows(cn.iocoder.yudao.framework.common.exception.ServiceException.class,()->service.decide(old,1L));}
 @Test void businessContextDraftAndReviewAndConfirmationUseDifferentGates(){long id=create("TEST business");HrmPayrollRequirementSaveReqVO q=JsonUtils.parseObject(JsonUtils.toJsonString(rows.selectById(id)),HrmPayrollRequirementSaveReqVO.class);q.setBusinessContextJson("{}");reqs.save(q,1L);q.setVersion(rows.selectById(id).getVersion());q.setStatus("REVIEWING");assertThrows(cn.iocoder.yudao.framework.common.exception.ServiceException.class,()->reqs.save(q,1L));assertThrows(cn.iocoder.yudao.framework.common.exception.ServiceException.class,()->confirm(id));q.setBusinessContextJson(business());reqs.save(q,1L);confirm(id);assertEquals("CONFIRMED",rows.selectById(id).getStatus());}
 @Test void hiddenReplacementIsClippedInCurrentDetail(){long a=create("Visible removed"),b=create("Hidden retained");Decision c=ctx(new Decision(),a);c.setDecision("REMOVED");c.setRemovalKind("DUPLICATE");c.setReplacementId(b);service.decide(c,1L);grants.delete(new LambdaQueryWrapperX<HrmPayrollRequirementProjectGrantDO>().eq(HrmPayrollRequirementProjectGrantDO::getUserId,3L));grant(3,"READ,EXPORT","["+a+"]");Map<?,?>metadata=JsonUtils.parseObject(service.detail(p,a,3L).getScopeDecisionJson(),Map.class);assertFalse(metadata.containsKey("replacementId"));assertEquals(true,metadata.get("replacementRestricted"));assertThrows(cn.iocoder.yudao.framework.common.exception.ServiceException.class,()->service.detail(p,b,3L));assertNotNull(JsonUtils.parseObject(rows.selectById(a).getScopeDecisionJson(),Map.class).get("replacementId"));}
 @Test void structuredDeferredStatusCannotBypassIndependentDecision(){long id=create("TEST no alias");HrmPayrollRequirementSaveReqVO q=JsonUtils.parseObject(JsonUtils.toJsonString(rows.selectById(id)),HrmPayrollRequirementSaveReqVO.class);q.setStatus("DEFERRED");assertThrows(cn.iocoder.yudao.framework.common.exception.ServiceException.class,()->reqs.save(q,1L));assertEquals("CANDIDATE",rows.selectById(id).getScopeDecision());}
 @Test void inAppReminderInboxRequiresCurrentReadAndExactRecipient(){long id=create("TEST inbox");Collaboration c=ctx(new Collaboration(),id);c.setKind("REMINDER");c.setReference("TEST private scoped reminder");c.setRecipientId(3L);service.collaborate(c,1L);assertEquals(1,service.reminders(p,3L).size());assertTrue(service.reminders(p,1L).isEmpty());assertTrue(service.reminders(p,2L).isEmpty());grants.delete(new LambdaQueryWrapperX<HrmPayrollRequirementProjectGrantDO>().eq(HrmPayrollRequirementProjectGrantDO::getUserId,3L));assertThrows(cn.iocoder.yudao.framework.common.exception.ServiceException.class,()->service.reminders(p,3L));}
}
